/**
 * proactiveNativeBridge.ts
 * TypeScript bridge between WebView proactive state and Android WorkManager native background plugin.
 *
 * Responsibilities:
 * - Idempotently register/cancel Android 1-hour WorkManager PeriodicWorkRequest (ZERO immediate checks on App start!)
 * - Non-destructively sync compact, privacy-safe proactive state (no Base64 avatars/images) to Android SharedPreferences
 * - Schedule/cancel unique OneTimeWorkRequests for unreplied follow-up steps (+15m -> +60m) and followUpAt
 * - Drain messages generated by Android background workers when App was closed and idempotently merge into ChatDB
 */

import { Capacitor, registerPlugin } from '@capacitor/core';
import { ApiLog, ChatMessage, ProactiveEpisode } from '../../types';
import {
  loadProactiveSettings,
  saveProactiveSettings,
  loadProactiveRuntimeState,
  saveProactiveRuntimeState,
  loadProactiveEpisodes,
  saveProactiveEpisodes,
  normalizeProactiveEpisode,
  registerProactiveStoreNativeHooks,
  markMessageIdExecuted,
  markStepIdExecuted,
} from './proactiveStore';
import { loadCharacters, loadUserProfile, loadApiConfig } from '../storage';
import { mutateCharactersAtomic } from '../characterPersistence';
import { getRecentChatMessages, hasChatMessage, saveChatMessage } from '../chatDb';
import { permissionManager } from '../agent/PermissionManager';
import { getLifeEventsSync } from '../lifeState/lifeStateStore';
import { aiReplyTaskManager } from '../aiReply/AiReplyTaskManager';
import { getAllOfflineAiIds } from '../offline/offlineInteractionState';
import { persistApiLog } from '../apiLogger';

interface ProactiveBackgroundPluginInterface {
  ensureHourlyWorkerRegistered(options: { enabled: boolean }): Promise<{
    registered: boolean;
    workName: string;
    intervalHours?: number;
  }>;
  syncState(options: { snapshotJson: string }): Promise<{ synced: boolean }>;
  scheduleFollowUpStep(options: {
    episodeId: string;
    aiId: string;
    stepId: string;
    delayMinutes: number;
  }): Promise<{ scheduled: boolean; workTag?: string }>;
  scheduleFollowUpAt(options: {
    episodeId: string;
    aiId: string;
    eventId: string;
    targetTimestampMs: number;
  }): Promise<{ scheduled: boolean }>;
  cancelEpisodeWork(options: { episodeId: string }): Promise<{ cancelled: boolean }>;
  drainPendingInbox(): Promise<{ payloadJson: string }>;
  getWorkerStatus(): Promise<{
    registered: boolean;
    state: string;
    workName?: string;
    intervalHours?: number;
    lastInspectionAt?: number;
    lastInspectionSummary?: string;
    pausedUntil?: number;
    pauseReason?: string;
  }>;
}

const ProactiveBackground = registerPlugin<ProactiveBackgroundPluginInterface>('ProactiveBackground');

export interface NativeWorkerStatus {
  isAndroidNative: boolean;
  registered: boolean;
  state: string;
  intervalHours: number;
  lastInspectionAt: number;
  lastInspectionSummary: string;
  pausedUntil?: number;
  pauseReason?: string;
}

let syncTimer: ReturnType<typeof setTimeout> | null = null;
let hooksRegistered = false;

export function isAndroidNativeRuntime(): boolean {
  try {
    return Capacitor.isNativePlatform() && Capacitor.getPlatform() === 'android';
  } catch {
    return false;
  }
}

export function initProactiveNativeStoreHooks(): void {
  if (hooksRegistered) return;
  hooksRegistered = true;
  registerProactiveStoreNativeHooks({
    onEpisodeCancelled: (episodeId) => {
      void cancelNativeEpisodeWork(episodeId);
    },
    onStateMutated: (opts) => {
      scheduleDebouncedNativeSync(opts);
    },
  });
}

export function scheduleDebouncedNativeSync(opts?: { pauseExplicitlyCleared?: boolean }): void {
  if (!isAndroidNativeRuntime()) return;
  if (syncTimer) {
    clearTimeout(syncTimer);
  }
  syncTimer = setTimeout(() => {
    syncTimer = null;
    void syncProactiveStateToNative(opts);
  }, 400);
}

/**
 * Idempotently register or cancel the unique 1-hour Android WorkManager task.
 * NEVER triggers an immediate proactive evaluation on App startup.
 */
export async function ensureHourlyAndroidWorkerRegistered(): Promise<{
  registered: boolean;
  workName?: string;
}> {
  const settings = loadProactiveSettings();
  const shouldEnable = Boolean(settings.enabled && settings.androidBackgroundEnabled !== false);

  if (!isAndroidNativeRuntime()) {
    return { registered: false };
  }
  try {
    const res = await ProactiveBackground.ensureHourlyWorkerRegistered({ enabled: shouldEnable });
    return { registered: Boolean(res?.registered), workName: res?.workName };
  } catch (e) {
    console.warn('[ProactiveNativeBridge] ensureHourlyWorkerRegistered failed:', e);
    return { registered: false };
  }
}

/**
 * Build and sync compact, privacy-safe proactive state snapshot to Android SharedPreferences.
 * Strips Base64 avatars/images and keeps at most 20 lean recent messages per permitted AI.
 */
export async function syncProactiveStateToNative(opts?: {
  pauseExplicitlyCleared?: boolean;
}): Promise<boolean> {
  if (!isAndroidNativeRuntime()) return false;

  try {
    const settings = loadProactiveSettings();
    const runtimeState = loadProactiveRuntimeState();
    const episodes = loadProactiveEpisodes();
    const characters = loadCharacters();
    const userProfile = loadUserProfile();
    const apiConfig = loadApiConfig();
    const lifeEvents = getLifeEventsSync({ status: ['pending', 'ongoing', 'waiting'] });

    const aiPermissions: Record<string, string> = {};
    const thinkingAiIds: string[] = [];
    const leanCharacters: any[] = [];

    for (const ch of characters) {
      const aiCfg = permissionManager.getAiConfig(ch.id);
      const perm = aiCfg?.permissions?.['proactive_chat'] || 'ALLOW';
      aiPermissions[ch.id] = perm;

      if (aiReplyTaskManager.isCharacterThinking(ch.id)) {
        thinkingAiIds.push(ch.id);
      }

      const recentMsgs = await getRecentChatMessages(ch.id, 20).catch(() => []);
      const leanMsgs = recentMsgs.map((m) => ({
        id: m.id,
        sender: m.sender,
        text: (m.text || '').slice(0, 260),
        timestamp: m.timestamp,
        isProactive: Boolean(m.isProactive),
      }));

      leanCharacters.push({
        id: ch.id,
        name: ch.name,
        persona: (ch.persona || '').slice(0, 600),
        personality: (ch.personality || '').slice(0, 200),
        relationship: (ch.relationship || '').slice(0, 100),
        modelName: ch.modelConfig?.modelName || '',
        recentMessages: leanMsgs,
      });
    }

    const now = new Date();
    const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

    let weatherSnapshot: any = null;
    try {
      const rawWeather = localStorage.getItem('phone_weather_cache_v1');
      if (rawWeather) {
        const parsedW = JSON.parse(rawWeather);
        weatherSnapshot = parsedW?.data || parsedW || null;
      }
    } catch {
      weatherSnapshot = null;
    }

    const snapshot = {
      syncedAt: Date.now(),
      settings,
      pausedUntil: settings.pausedUntil || 0,
      pauseReason: settings.pauseReason || '',
      pauseExplicitlyCleared: Boolean(opts?.pauseExplicitlyCleared),
      doNotDisturbToday: permissionManager.isDoNotDisturbToday(),
      doNotDisturbDate: todayStr,
      quotaExhaustedUntil: runtimeState.quotaExhaustedUntil || 0,
      userName: userProfile?.name || '用户',
      aiPermissions,
      thinkingAiIds,
      offlineAiIds: getAllOfflineAiIds(),
      characters: leanCharacters,
      episodes,
      runtimeState,
      lifeEvents: lifeEvents.slice(0, 20),
      weatherSnapshot,
      apiConfig: {
        textProvider: apiConfig?.textProvider || apiConfig?.textApiConfig?.provider || 'gemini',
        textBaseUrl: apiConfig?.textBaseUrl || apiConfig?.textApiConfig?.baseUrl || '',
        textApiKey: apiConfig?.textApiKey || apiConfig?.textApiConfig?.apiKey || '',
        textModel: apiConfig?.textModel || apiConfig?.textApiConfig?.model || 'gemini-2.5-flash',
        customHeaders: apiConfig?.customHeaders || {},
      },
    };

    await ProactiveBackground.syncState({ snapshotJson: JSON.stringify(snapshot) });
    return true;
  } catch (e) {
    console.warn('[ProactiveNativeBridge] syncProactiveStateToNative failed:', e);
    return false;
  }
}

export async function scheduleNativeFollowUpStep(params: {
  episodeId: string;
  aiId: string;
  stepId: string;
  delayMinutes: number;
}): Promise<boolean> {
  if (!isAndroidNativeRuntime()) return false;
  try {
    await syncProactiveStateToNative();
    const res = await ProactiveBackground.scheduleFollowUpStep(params);
    return Boolean(res?.scheduled);
  } catch (e) {
    console.warn('[ProactiveNativeBridge] scheduleNativeFollowUpStep failed:', e);
    return false;
  }
}

export async function scheduleNativeFollowUpAt(params: {
  episodeId: string;
  aiId: string;
  eventId: string;
  targetTimestampMs: number;
}): Promise<boolean> {
  if (!isAndroidNativeRuntime()) return false;
  try {
    await syncProactiveStateToNative();
    const res = await ProactiveBackground.scheduleFollowUpAt(params);
    return Boolean(res?.scheduled);
  } catch (e) {
    console.warn('[ProactiveNativeBridge] scheduleNativeFollowUpAt failed:', e);
    return false;
  }
}

export async function cancelNativeEpisodeWork(episodeId: string): Promise<boolean> {
  if (!isAndroidNativeRuntime() || !episodeId) return false;
  try {
    const res = await ProactiveBackground.cancelEpisodeWork({ episodeId });
    return Boolean(res?.cancelled);
  } catch (e) {
    console.warn('[ProactiveNativeBridge] cancelNativeEpisodeWork failed:', e);
    return false;
  }
}

/**
 * Drain messages persisted by Android native WorkManager workers while the App was closed,
 * and idempotently merge them into ChatDB IndexedDB + localStorage state.
 * Makes ZERO AI API calls!
 */
export async function drainAndMergeNativeInbox(): Promise<{
  mergedCount: number;
  lastInspectionAt?: number;
  lastInspectionSummary?: string;
}> {
  if (!isAndroidNativeRuntime()) {
    return { mergedCount: 0 };
  }

  try {
    const res = await ProactiveBackground.drainPendingInbox();
    if (!res?.payloadJson) return { mergedCount: 0 };

    const payload = JSON.parse(res.payloadJson);
    const inboxMessages: ChatMessage[] = Array.isArray(payload.messages) ? payload.messages : [];
    const nativeApiLogs: ApiLog[] = Array.isArray(payload.apiLogs) ? payload.apiLogs : [];
    const unreadDeltaByChar = new Map<string, number>();
    let mergedCount = 0;

    // Native WorkManager calls the provider while WebView is closed. Merge those
    // durable records into the same monitor store before processing messages.
    for (const nativeLog of nativeApiLogs) {
      if (!nativeLog || !nativeLog.id || !nativeLog.appName) continue;
      persistApiLog(nativeLog);
    }

    // 1. Idempotently write background messages into ChatDB IndexedDB
    for (const rawMsg of inboxMessages) {
      if (!rawMsg || !rawMsg.id || !rawMsg.characterId || !rawMsg.text) continue;
      const alreadyExists = await hasChatMessage(rawMsg.id).catch(() => false);
      if (alreadyExists) {
        markMessageIdExecuted(rawMsg.id);
        continue;
      }

      const msg: ChatMessage = {
        id: String(rawMsg.id),
        characterId: String(rawMsg.characterId),
        sender: 'ai',
        text: String(rawMsg.text),
        timestamp: typeof rawMsg.timestamp === 'number' ? rawMsg.timestamp : Date.now(),
        turnId: rawMsg.turnId,
        turnBubbleIndex: rawMsg.turnBubbleIndex,
        turnTotalBubbles: rawMsg.turnTotalBubbles,
        isProactive: true,
        proactiveMeta: {
          ...(rawMsg.proactiveMeta || {}),
          fromBackgroundWorker: true,
        },
      };

      await saveChatMessage(msg);
      markMessageIdExecuted(msg.id);
      if (msg.proactiveMeta?.episodeId && msg.proactiveMeta?.stepId) {
        markStepIdExecuted(msg.proactiveMeta.episodeId, msg.proactiveMeta.stepId);
      }

      unreadDeltaByChar.set(msg.characterId, (unreadDeltaByChar.get(msg.characterId) || 0) + 1);
      mergedCount++;
    }

    // 2. Update character unread counts for newly merged background messages atomically
    if (unreadDeltaByChar.size > 0) {
      await mutateCharactersAtomic((latestChars) => {
        let anyUpdated = false;
        const nextChars = latestChars.map((c) => {
          const delta = unreadDeltaByChar.get(c.id) || 0;
          if (delta > 0) {
            anyUpdated = true;
            return { ...c, unreadAiCount: (c.unreadAiCount || 0) + delta };
          }
          return c;
        });
        return anyUpdated ? nextChars : null;
      }).catch((err) => {
        console.warn('[ProactiveNativeBridge] Failed to update unreadAiCount:', err);
      });
    }

    // 3. Reconcile pausedUntil (keep max) without overwriting user's other settings
    const nativePausedUntil = typeof payload.pausedUntil === 'number' ? payload.pausedUntil : 0;
    if (nativePausedUntil > Date.now()) {
      const settings = loadProactiveSettings();
      if (!settings.pausedUntil || nativePausedUntil > settings.pausedUntil) {
        saveProactiveSettings({
          ...settings,
          pausedUntil: nativePausedUntil,
          pauseReason: payload.pauseReason || settings.pauseReason || 'AI后台开启临时免打扰',
        });
      }
    }

    // 4. Reconcile native episodes non-destructively (newer updatedAt wins per episodeId)
    if (Array.isArray(payload.episodes) && payload.episodes.length > 0) {
      const localEpisodes = loadProactiveEpisodes();
      const byId = new Map<string, ProactiveEpisode>();
      for (const ep of localEpisodes) {
        byId.set(ep.episodeId, ep);
      }
      let episodesChanged = false;
      for (const rawEp of payload.episodes) {
        const normalized = normalizeProactiveEpisode(rawEp);
        if (!normalized) continue;
        const existing = byId.get(normalized.episodeId);
        if (!existing || (normalized.updatedAt || 0) > (existing.updatedAt || 0)) {
          byId.set(normalized.episodeId, normalized);
          episodesChanged = true;
        }
      }
      if (episodesChanged) {
        saveProactiveEpisodes(Array.from(byId.values()));
      }
    }

    // 5. Reconcile runtimeState (quotaExhaustedUntil, handledEventIds, daily counts)
    if (payload.runtimeState && typeof payload.runtimeState === 'object') {
      const localRt = loadProactiveRuntimeState();
      const nativeQuota = typeof payload.quotaExhaustedUntil === 'number' ? payload.quotaExhaustedUntil : 0;
      if (nativeQuota > (localRt.quotaExhaustedUntil || 0)) {
        localRt.quotaExhaustedUntil = nativeQuota;
      }
      if (typeof payload.lastInspectionAt === 'number' && payload.lastInspectionAt > localRt.lastGlobalCheckAt) {
        localRt.lastGlobalCheckAt = payload.lastInspectionAt;
      }
      const nativeCharStates = payload.runtimeState.characterStates || {};
      for (const [charId, rawCr] of Object.entries<any>(nativeCharStates)) {
        if (!rawCr || typeof rawCr !== 'object') continue;
        const localCr = localRt.characterStates[charId];
        if (!localCr) {
          localRt.characterStates[charId] = rawCr;
        } else {
          localCr.lastProactiveMsgAt = Math.max(localCr.lastProactiveMsgAt || 0, rawCr.lastProactiveMsgAt || 0);
          localCr.lastConversationAt = Math.max(localCr.lastConversationAt || 0, rawCr.lastConversationAt || 0);
          localCr.lastUserMsgAt = Math.max(localCr.lastUserMsgAt || 0, rawCr.lastUserMsgAt || 0);
          if (rawCr.lastCountResetDateStr === localCr.lastCountResetDateStr) {
            localCr.dailyProactiveCount = Math.max(localCr.dailyProactiveCount || 0, rawCr.dailyProactiveCount || 0);
          }
          const mergedEvents = new Set<string>([
            ...(localCr.handledEventIds || []),
            ...(Array.isArray(rawCr.handledEventIds) ? rawCr.handledEventIds : []),
          ]);
          localCr.handledEventIds = Array.from(mergedEvents).slice(-60);
        }
      }
      saveProactiveRuntimeState(localRt);
    }

    if (mergedCount > 0 && typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('ai_proactive_message_received', { detail: { mergedCount } }));
      window.dispatchEvent(new Event('storage'));
    }

    return {
      mergedCount,
      lastInspectionAt: typeof payload.lastInspectionAt === 'number' ? payload.lastInspectionAt : undefined,
      lastInspectionSummary:
        typeof payload.lastInspectionSummary === 'string' ? payload.lastInspectionSummary : undefined,
    };
  } catch (e) {
    console.warn('[ProactiveNativeBridge] drainAndMergeNativeInbox failed:', e);
    return { mergedCount: 0 };
  }
}

export async function getNativeWorkerStatus(): Promise<NativeWorkerStatus> {
  if (!isAndroidNativeRuntime()) {
    const rt = loadProactiveRuntimeState();
    const settings = loadProactiveSettings();
    return {
      isAndroidNative: false,
      registered: false,
      state: 'WEB_PREVIEW',
      intervalHours: 1,
      lastInspectionAt: rt.lastGlobalCheckAt || 0,
      lastInspectionSummary: '当前为 Web 预览环境，Android WorkManager 后台巡检将在 APK 中自动生效',
      pausedUntil: settings.pausedUntil,
      pauseReason: settings.pauseReason,
    };
  }

  try {
    const res = await ProactiveBackground.getWorkerStatus();
    return {
      isAndroidNative: true,
      registered: Boolean(res?.registered),
      state: res?.state || 'UNKNOWN',
      intervalHours: res?.intervalHours || 1,
      lastInspectionAt: res?.lastInspectionAt || 0,
      lastInspectionSummary: res?.lastInspectionSummary || '已注册 Android 每小时本地巡检',
      pausedUntil: res?.pausedUntil,
      pauseReason: res?.pauseReason,
    };
  } catch {
    return {
      isAndroidNative: true,
      registered: false,
      state: 'ERROR',
      intervalHours: 1,
      lastInspectionAt: 0,
      lastInspectionSummary: '查询 Android WorkManager 状态失败',
    };
  }
}
